// End-to-end UI test: drives the real NayanPDF Electron app (renderer + main
// process + engine) the way a user would. Uses fixtures generated by the engine
// test suite (engine/tests/_fixtures). Writes screenshots and results to
// test-results/ui/.
//
//   node scripts/ui-e2e.mjs            (Linux: run under xvfb-run)
import { _electron as electron } from "playwright-core";
import { existsSync, mkdirSync, rmSync, writeFileSync, copyFileSync, statSync } from "node:fs";
import { join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { execFileSync } from "node:child_process";

const root = resolve(fileURLToPath(new URL("..", import.meta.url)));
const IS_WIN = process.platform === "win32";
const fx = join(root, "engine/tests/_fixtures");
const out = join(root, "test-results/ui");
const work = join(out, "work");
rmSync(out, { recursive: true, force: true });
mkdirSync(work, { recursive: true });
const dialogFile = join(out, "dialogs.json");
const results = [];
const PY = process.env.NAYANPDF_PYTHON || (IS_WIN ? "python.exe" : "/opt/nayan-venv/bin/python");

function setDialogs(obj) {
  writeFileSync(dialogFile, JSON.stringify(obj));
}
function record(name, ok, detail = "") {
  results.push({ name, ok, detail });
  console.log(`${ok ? "PASS" : "FAIL"} ${name} ${detail}`);
}
function pdfText(path) {
  return execFileSync(PY, ["-c", "import pymupdf,sys; d=pymupdf.open(sys.argv[1]); print('\\n'.join(p.get_text() for p in d)); print('PAGES', d.page_count); print('ANNOTS', sum(len(list(p.annots())) for p in d)); print('IMAGES', sum(len(p.get_images()) for p in d))", path]).toString();
}

for (const f of ["financial.pdf", "form.pdf", "a.pdf", "b.pdf", "c.pdf", "notes.pdf", "twenty.pdf", "scanned.pdf"]) {
  if (!existsSync(join(fx, f))) {
    console.error(`missing fixture ${f}: run 'python -m pytest engine/tests' first`);
    process.exit(2);
  }
  copyFileSync(join(fx, f), join(work, f));
}
const src = join(work, "financial.pdf");
setDialogs({});

const app = await electron.launch({
  executablePath: join(root, "node_modules", "electron", "dist", IS_WIN ? "electron.exe" : "electron"),
  // The Chromium sandbox cannot run as root in a Linux container; Windows keeps it.
  args: [...(IS_WIN ? [] : ["--no-sandbox"]), root, src],
  env: { ...process.env, NAYANPDF_PYTHON: PY, NAYANPDF_TEST_DIALOGS: dialogFile, NAYANPDF_TEST_USERDATA: join(out, "profile"), ELECTRON_DISABLE_SECURITY_WARNINGS: "1" },
  timeout: 60000,
});
app.process().stdout.on("data", (d) => process.stdout.write(String(d).split("\n").filter((l) => l.startsWith("[testhook]")).map((l) => "  " + l + "\n").join("")));
const page = await app.firstWindow();
page.setDefaultTimeout(30000);
await page.setViewportSize({ width: 1440, height: 900 }).catch(() => undefined);
const shot = async (name) => page.screenshot({ path: join(out, `${name}.png`) });
const only = process.env.UI_ONLY ? new RegExp(process.env.UI_ONLY, "i") : null;
const step = async (name, fn) => {
  if (only && !only.test(name)) return;
  try {
    await fn();
  } catch (e) {
    record(name, false, String(e.message || e).split("\n")[0]);
    await shot(`fail-${name.replace(/\W+/g, "_")}`).catch(() => undefined);
  }
};
const textLayer = () => page.evaluate(() => Array.from(document.querySelectorAll(".pdfViewer .textLayer")).map((e) => e.textContent).join(" "));
const docRevision = async () => page.evaluate(() => document.querySelector('[title="Undo (Ctrl+Z)"]')?.hasAttribute("disabled"));
const waitIdle = async () => {
  await page.waitForTimeout(300);
  await page.waitForSelector(".busy-veil", { state: "detached", timeout: 120000 });
};

try {
  await step("Document opens from the command line and renders", async () => {
    await page.waitForSelector(".tab .name", { timeout: 60000 });
    await page.waitForSelector(".pdfViewer .page canvas", { timeout: 60000 });
    const name = await page.textContent(".tab .name");
    const pages = await page.locator(".pdfViewer .page").count();
    await shot("01-document-open");
    record("Document opens from the command line and renders", name === "financial.pdf" && pages >= 1, `tab=${name}, pages=${pages}`);
  });

  await step("Thumbnails, zoom and page navigation", async () => {
    await page.waitForSelector(".thumb-item canvas");
    const before = await page.textContent(".zoom-label");
    await page.click('[title="Zoom in (Ctrl++)"]');
    await page.waitForTimeout(500);
    const after = await page.textContent(".zoom-label");
    await page.click('[title="Next page"]');
    await page.waitForTimeout(600);
    const pageNo = await page.inputValue(".page-input");
    record("Thumbnails, zoom and page navigation", before !== after && pageNo === "2", `zoom ${before} -> ${after}, page ${pageNo}`);
    await page.click('[title="Fit width (Ctrl+0)"]');
  });

  await step("Search within the document", async () => {
    await page.keyboard.press("Control+f");
    await page.fill(".find-bar input", "Opening balance");
    await page.waitForTimeout(1500);
    const count = await page.textContent(".find-bar .subtle");
    await shot("02-search");
    record("Search within the document", /\d+ \/ (\d+)/.test(count || "") && !/ \/ 0$/.test(count), `matches: ${count}`);
    await page.keyboard.press("Escape");
  });

  await step("Edit existing text in place", async () => {
    await page.click('[title="Previous page"]');
    await page.click('.mode-tabs button:has-text("Edit")');
    const line = page.locator('.ov-line[data-text="1,23,456.78"]').first();
    await line.waitFor({ timeout: 30000 });
    await line.click();
    await page.fill(".inline-editor textarea", "1,25,000.00");
    await page.keyboard.press("Enter");
    await waitIdle();
    await page.waitForFunction(() => document.querySelector(".pdfViewer .textLayer")?.textContent?.includes("1,25,000.00"), null, { timeout: 30000 });
    const t = await textLayer();
    await shot("03-edit-text");
    record("Edit existing text in place", t.includes("1,25,000.00") && !t.includes("1,23,456.78 98,765.43"), "value replaced in page content");
  });

  await step("Undo and redo", async () => {
    await page.keyboard.press("Escape");
    await page.click('[title="Undo (Ctrl+Z)"]');
    await page.waitForFunction(() => document.querySelector(".pdfViewer .textLayer")?.textContent?.includes("1,23,456.78"), null, { timeout: 30000 });
    await page.click('[title="Redo (Ctrl+Y)"]');
    await page.waitForFunction(() => document.querySelector(".pdfViewer .textLayer")?.textContent?.includes("1,25,000.00"), null, { timeout: 30000 });
    record("Undo and redo", true, "revision toggled back and forth");
  });

  await step("Highlight and sticky note annotations", async () => {
    await page.click('.mode-tabs button:has-text("Comment")');
    await page.click('button[title="Highlight"]');
    const pg = page.locator(".pdfViewer .page").first();
    const box = await pg.boundingBox();
    // Drag across the title line near the top of page 1.
    const y = box.y + box.height * 0.135;
    await page.mouse.move(box.x + box.width * 0.12, y);
    await page.mouse.down();
    await page.mouse.move(box.x + box.width * 0.6, y + 8, { steps: 8 });
    await page.mouse.up();
    await waitIdle();
    await page.click('button[title="Sticky note"]');
    await page.mouse.click(box.x + box.width * 0.85, box.y + box.height * 0.3);
    await page.fill(".edit-pop textarea", "Check revenue against ledger");
    await page.keyboard.press("Enter");
    await waitIdle();
    await page.waitForTimeout(800);
    const items = await page.locator(".side.right .list-item").count();
    await shot("04-annotations");
    record("Highlight and sticky note annotations", items >= 2, `${items} comments listed`);
  });

  await step("Save As writes a new file and leaves the original untouched", async () => {
    const before = statSync(src).mtimeMs;
    const target = join(work, "financial_edited.pdf");
    setDialogs({ saveAs: target });
    await page.click('button:has-text("Save As")');
    await page.waitForTimeout(1500);
    const t = pdfText(target);
    const ok = existsSync(target) && t.includes("1,25,000.00") && /ANNOTS [2-9]/.test(t) && statSync(src).mtimeMs === before && pdfText(src).includes("1,23,456.78");
    record("Save As writes a new file and leaves the original untouched", ok, `edited file has new value + annotations; original unchanged`);
  });

  await step("Organize pages: delete a page and apply", async () => {
    await page.click('.mode-tabs button:has-text("Pages")');
    await page.waitForSelector(".org-item");
    const n0 = await page.locator(".org-item").count();
    await page.locator(".org-item").nth(1).click();
    await page.click('.ws-toolbar button:has-text("Delete")');
    await page.click('button:has-text("Apply changes")');
    await page.click('.modal-foot button:has-text("Apply")');
    await waitIdle();
    await page.waitForTimeout(1500);
    const n1 = await page.locator(".org-item").count();
    await shot("05-organize");
    record("Organize pages: delete a page and apply", n1 === n0 - 1, `${n0} -> ${n1} pages`);
  });

  await step("Redact a PAN pattern permanently", async () => {
    await page.click('.doc-pane.active .mode-tabs button:has-text("Redact")');
    await page.click('label.check:has-text("PAN (India)") input');
    await page.click('button:has-text("Find and mark")');
    await page.waitForSelector(".ov-redact", { timeout: 30000 });
    setDialogs({ confirm: 0 });
    await page.click('button:has-text("Apply redactions")');
    await waitIdle();
    await page.waitForTimeout(1500);
    const t = await textLayer();
    await shot("06-redact");
    const notice = await page.locator(".doc-pane.active .notice.ok").count();
    const target = join(work, "financial_redacted.pdf");
    setDialogs({ saveAs: target });
    await page.locator('.doc-pane.active button:has-text("Save As")').click();
    await page.waitForTimeout(1500);
    const saved = pdfText(target);
    record("Redact a PAN pattern permanently", !t.includes("ABCDE1234F") && notice > 0 && !saved.includes("ABCDE1234F") && saved.includes("Statement of Profit"), "PAN (incl. inside GSTIN) absent from viewer and saved file; verification passed");
  });

  await step("Sign: create a typed signature and place it", async () => {
    await page.click('.mode-tabs button:has-text("Sign")');
    await page.click('.sig-item:has-text("+ New")');
    await page.click('.modal button:has-text("Type")');
    await page.fill('.modal input[placeholder="Type your name"]', "N K Patel");
    await page.waitForSelector(".modal .sig-item img");
    await page.click('.modal-foot button:has-text("Save")');
    await page.waitForTimeout(500);
    const pg = page.locator(".pdfViewer .page").first();
    const box = await pg.boundingBox();
    await page.mouse.click(box.x + box.width * 0.55, Math.min(box.y + box.height * 0.6, 820));
    await waitIdle();
    await page.waitForTimeout(800);
    const target = join(work, "financial_signed_image.pdf");
    setDialogs({ saveAs: target });
    await page.click('button:has-text("Save As")');
    await page.waitForTimeout(1500);
    const t = pdfText(target);
    await shot("07-sign");
    record("Sign: create a typed signature and place it", /IMAGES [1-9]/.test(t), "signature image embedded in saved file");
  });

  await step("Fill a PDF form", async () => {
    setDialogs({ openFiles: [join(work, "form.pdf")] });
    await page.click('button[title="Open PDF (Ctrl+O)"]');
    await page.waitForSelector('.tab.active .name:has-text("form.pdf")');
    await page.waitForSelector(".doc-pane.active .pdfViewer .page canvas");
    await page.locator(".doc-pane.active .mode-tabs button:has-text('Forms')").click();
    await page.waitForSelector(".doc-pane.active .side.right input.input");
    await page.locator(".doc-pane.active .side.right input.input").first().fill("ACME Traders");
    await page.locator('.doc-pane.active .side.right button:has-text("Apply")').click();
    await waitIdle();
    const target = join(work, "form_filled.pdf");
    setDialogs({ saveAs: target });
    await page.locator('.doc-pane.active button:has-text("Save As")').click();
    await page.waitForTimeout(1500);
    const v = execFileSync(PY, ["-c", "import pymupdf,sys; d=pymupdf.open(sys.argv[1]); print([w.field_value for p in d for w in p.widgets() if w.field_name=='client_name'])", target]).toString();
    await shot("08-forms");
    record("Fill a PDF form", v.includes("ACME Traders"), v.trim());
  });

  await step("Compress tool reports measured sizes", async () => {
    await page.click('.rail-btn:has-text("Tools")');
    await page.click('.list-item:has-text("Compress PDF")');
    setDialogs({ openFiles: [join(work, "twenty.pdf")] });
    await page.click('button:has-text("Choose file")');
    await page.click('button.primary:has-text("Compress")');
    await page.waitForSelector(".result-box .stat-grid", { timeout: 120000 });
    const stats = await page.textContent(".result-box .stat-grid");
    await shot("09-compress");
    record("Compress tool reports measured sizes", /Original.*Compressed/.test(stats || ""), (stats || "").replace(/\s+/g, " "));
  });

  await step("Convert PDF to Excel", async () => {
    await page.click('.rail-btn:has-text("Convert")');
    setDialogs({ openFiles: [join(work, "financial.pdf")] });
    await page.click('button:has-text("Choose file")');
    await page.click('.tool-card:has-text("Excel / CSV")');
    await page.click('button.primary:has-text("Convert")');
    await page.waitForSelector('.result-box strong:has-text("Completed")', { timeout: 180000 });
    const xlsx = join(work, "financial.xlsx");
    await shot("10-convert-excel");
    record("Convert PDF to Excel", existsSync(xlsx), xlsx);
  });

  await step("Batch: valid files succeed, invalid file fails, queue continues", async () => {
    await page.click('.rail-btn:has-text("Batch")');
    setDialogs({ openFiles: [join(work, "a.pdf"), join(work, "notes.pdf"), join(work, "b.pdf")], pickOutputDir: join(work, "batch") });
    mkdirSync(join(work, "batch"), { recursive: true });
    await page.click('button:has-text("Add files")');
    await page.click('.card button:has-text("Change")');
    await page.click('button:has-text("Start")');
    await page.waitForFunction(() => document.querySelectorAll("tbody .badge.ok, tbody .badge.err").length >= 3, null, { timeout: 180000 });
    const ok = await page.locator("tbody .badge.ok").count();
    const err = await page.locator("tbody .badge.err").count();
    await shot("11-batch");
    record("Batch: valid files succeed, invalid file fails, queue continues", ok === 2 && err === 1, `${ok} succeeded, ${err} failed`);
  });


  const toolPage = async (name) => {
    await page.click('.rail-btn:has-text("Tools")');
    await page.click(`.list-item:has-text("${name}")`);
  };
  const runAndWait = async (label, timeout = 180000) => {
    await page.click(`button.primary:has-text("${label}")`);
    await page.waitForSelector('.result-box strong:has-text("Completed"), .result-box strong:has-text("Failed")', { timeout });
    return page.textContent(".result-box");
  };

  await step("Merge tool combines files in order", async () => {
    await toolPage("Merge PDFs");
    setDialogs({ openFiles: [join(work, "a.pdf"), join(work, "b.pdf")] });
    await page.click('button:has-text("Add PDFs")');
    await page.waitForSelector(".file-row:nth-child(2) img.thumb");
    await page.fill('.field:has-text("Output file name") input', "merged_ab");
    const res = await runAndWait("Merge");
    const t = pdfText(join(work, "merged_ab.pdf"));
    await shot("14-merge");
    record("Merge tool combines files in order", /Completed/.test(res) && t.indexOf("A page 2") < t.indexOf("B page 1") && /PAGES 5/.test(t), "5 pages, A before B");
  });

  await step("Split tool: 20 pages into 4 files", async () => {
    await toolPage("Split PDF");
    setDialogs({ openFiles: [join(work, "twenty.pdf")] });
    await page.click('button:has-text("Choose file")');
    await page.fill('.card input[type="number"]', "5");
    const res = await runAndWait("Split");
    const n = await page.locator(".result-box .output-row").count();
    record("Split tool: 20 pages into 4 files", /Completed/.test(res) && n === 4, `${n} outputs`);
  });

  await step("OCR tool makes a scan searchable", async () => {
    await toolPage("OCR PDF");
    setDialogs({ openFiles: [join(work, "scanned.pdf")] });
    await page.click('button:has-text("Choose file")');
    await page.fill('.card input[placeholder="All pages"]', "1");
    const res = await runAndWait("Run OCR", 300000);
    const t = pdfText(join(work, "scanned_ocr.pdf"));
    await shot("15-ocr");
    record("OCR tool makes a scan searchable", /Completed/.test(res) && /Revenue/.test(t), "recognised text present in output");
  });

  await step("Protect tool adds a password (verified)", async () => {
    await toolPage("Protect PDF");
    setDialogs({ openFiles: [join(work, "a.pdf")] });
    await page.click('button:has-text("Choose file")');
    await page.fill('input[placeholder="Open password"]', "s3cret-pw");
    await page.fill('input[placeholder="Repeat"]', "s3cret-pw");
    const res = await runAndWait("Protect");
    const check = execFileSync(PY, ["-c", "import pymupdf,sys; d=pymupdf.open(sys.argv[1]); print(d.needs_pass, d.authenticate('s3cret-pw')>0)", join(work, "a_protected.pdf")]).toString().trim();
    record("Protect tool adds a password (verified)", /Completed/.test(res) && check === "1 True", check);
  });

  await step("Compare tool lists differences", async () => {
    await toolPage("Compare PDFs");
    setDialogs({ openFiles: [join(work, "c.pdf")] });
    await page.locator('.card:has-text("Original (A)") button:has-text("Choose file")').click();
    setDialogs({ openFiles: [join(work, "merged_ab.pdf")] });
    await page.locator('.card:has-text("Revised (B)") button:has-text("Choose file")').click();
    await page.click('button.primary:has-text("Compare")');
    await page.waitForSelector("text=difference(s)", { timeout: 120000 });
    await page.locator(".list-item").filter({ hasText: "modified" }).first().click().catch(() => undefined);
    await page.waitForTimeout(2500);
    const n = await page.locator(".list-item .badge").count();
    await shot("16-compare");
    record("Compare tool lists differences", n > 0, `${n} differences listed`);
  });

  await step("Convert PDF to Word and PowerPoint", async () => {
    await page.click('.rail-btn:has-text("Convert")');
    setDialogs({ openFiles: [join(work, "financial.pdf")] });
    await page.click('button:has-text("Choose file")');
    await page.click('.tool-card:has-text("Word")');
    let res = await runAndWait("Convert");
    const okW = existsSync(join(work, "financial.docx"));
    await page.click('.tool-card:has-text("PowerPoint")');
    res = await runAndWait("Convert");
    const okP = existsSync(join(work, "financial.pptx"));
    record("Convert PDF to Word and PowerPoint", okW && okP, `docx=${okW} pptx=${okP}`);
  });

  await step("Watermark with live preview applied to open document", async () => {
    await page.click(".tab:has-text('financial_signed_image.pdf')");
    await page.click('.doc-pane.active button:has-text("More tools")');
    await page.click('button:has-text("Watermark, header, page numbers")');
    await page.waitForSelector(".modal img", { timeout: 60000 });
    await shot("17-watermark-preview");
    await page.click('.modal-foot button:has-text("Apply")');
    await waitIdle();
    await page.waitForFunction(() => document.querySelector(".doc-pane.active .pdfViewer .textLayer")?.textContent?.includes("CONFIDENTIAL"), null, { timeout: 60000 });
    record("Watermark with live preview applied to open document", true, "preview rendered; watermark text in page");
  });

  await step("Digital signature with a new certificate (verified)", async () => {
    await page.click('.doc-pane.active .mode-tabs button[title="Sign"]');
    await page.click('.doc-pane.active button:has-text("Invisible")');
    await page.click('.modal button:has-text("Create...")');
    await page.fill('.modal >> nth=1 >> .field:has-text("Your name") input', "N K Patel Test");
    const pws = page.locator('.modal >> nth=1 >> input[type="password"]');
    await pws.nth(0).fill("cert-pass-1");
    await pws.nth(1).fill("cert-pass-1");
    setDialogs({ saveFile: join(work, "my-cert.pfx") });
    await page.click('.modal >> nth=1 >> button:has-text("Create")');
    await page.waitForFunction(() => document.querySelectorAll(".modal").length === 1, null, { timeout: 60000 });
    await page.click('.modal button:has-text("Check")');
    await page.waitForSelector(".modal .notice:has-text('N K Patel Test')");
    setDialogs({ saveFile: join(work, "financial_digitally_signed.pdf") });
    await page.click('.modal-foot button:has-text("Sign and save")');
    await page.waitForSelector('.toast:has-text("Document signed")', { timeout: 120000 });
    const v = execFileSync(PY, ["-c", "import sys; sys.path.insert(0,'engine'); from nayanpdf_engine.server import call; r=call('sign.verify', path=sys.argv[1]); s=r['signatures'][0]; print(s['intact'], s['valid'])", join(work, "financial_digitally_signed.pdf")], { cwd: root }).toString().trim();
    await shot("18-digital-signature");
    record("Digital signature with a new certificate (verified)", v.endsWith("True True"), `intact/valid: ${v.split("\n").pop()}`);
  });

  await step("Settings and dark theme", async () => {
    await page.click('.rail-btn:has-text("Settings")');
    await page.click('.seg button:has-text("Dark")');
    await page.waitForTimeout(500);
    const theme = await page.evaluate(() => document.documentElement.dataset.theme);
    await shot("12-settings-dark");
    await page.click('.rail-btn:has-text("Home")');
    await page.waitForTimeout(400);
    await shot("13-home-dark");
    await page.click('.rail-btn:has-text("Settings")');
    await page.click('.seg button:has-text("Light")');
    record("Settings and dark theme", theme === "dark", `theme=${theme}`);
  });

  await step("No network requests attempted by the renderer", async () => {
    const urls = await page.evaluate(() => performance.getEntriesByType("resource").map((e) => e.name).filter((u) => !/^(app|nayan-doc|data|blob):/.test(u)));
    record("No network requests attempted by the renderer", urls.length === 0, urls.slice(0, 3).join(", "));
  });
} finally {
  setDialogs({ closeConfirm: 0 });
  await Promise.race([app.close().catch(() => undefined), new Promise((r) => setTimeout(r, 15000))]);
  writeFileSync(join(out, "results.json"), JSON.stringify(results, null, 2));
  const failed = results.filter((r) => !r.ok).length;
  console.log(`UI E2E: ${results.length - failed}/${results.length} passed`);
  process.exit(failed ? 1 : 0);
}
